mod solution;

fn main() {
    let cases = [
    (r#"(id0,t0,d3),(id1,t1,d1),(id2,t1,d2)"#, r#"0,1,2"#),
    (r#"(id0,t0,d2),(id1,t0,d1),(id2,t3,d1)"#, r#"1,0,2"#),
    (r#"
(id0,t0,d2),(id1,t0,d1),(id2,t3,d1)
"#, r#"1,0,2"#),
    (r#"  
(id0,t0,d3),(id1,t1,d1),(id2,t1,d2)
  "#, r#"0,1,2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS priority-scheduling");
}
